// Brand marks for the Permissions catalog (Settings → Permissions), each on a
// white rounded "app icon" tile. Paths are the real logos — simple-icons
// (GitHub, LinkedIn, Docker, PostHog) and the official multicolor Gmail /
// Google Calendar SVGs — inlined following LoginPage.tsx's Google "G"
// precedent: no external image hosts (preview-safe), no icon dependency.
// Growth and Cursor are ours: no brand owns those two behaviors.
//
// Every icon also accepts `bare`, which skips the Tile (an HTML <span>, so it
// can't nest inside an SVG <g>) and returns the raw <svg> — used by
// BrainGraph.tsx to draw the same logos on brain nodes, which is pure SVG and
// draws its own background chip. `size` (bare only) sets the rendered box in
// px via explicit width/height attributes — not a transform scale, so there's
// no compound-transform math for a caller to get wrong when resizing.
// BRAND_ICONS below is the id-keyed lookup for that, keyed the same as
// toolCatalog.ts's BRAIN_TOOL_CATALOG.

import { cloneElement, type ComponentType, type ReactElement, type ReactNode, type SVGProps } from 'react';

export interface BrandIconProps {
  bare?: boolean;
  size?: number;
}

function Tile({ children }: { children: ReactNode }) {
  return (
    // rounded-[8px], not rounded-lg: index.css zeroes the radius tokens for the
    // app's square-corner look; the arbitrary value is the deliberate exception.
    <span className="flex h-9 w-9 shrink-0 items-center justify-center rounded-[8px] border border-hairline bg-white">
      {children}
    </span>
  );
}

function tileOrBare(
  bare: boolean | undefined,
  size: number | undefined,
  svg: ReactElement<SVGProps<SVGSVGElement>>,
): ReactNode {
  if (!bare) return <Tile>{svg}</Tile>;
  if (size == null) return svg;
  // Drop the className (its CSS h-6/w-6 would otherwise outrank the width/height
  // attributes) so `size` is the one thing controlling the rendered box.
  return cloneElement(svg, { width: size, height: size, className: undefined });
}

