/** Brands simple-icons does not carry (French finance SaaS, mostly): the
 *  initial on a rounded tile in the brand's colour — same Tile/bare contract. */
function letterIcon(letter: string, fill: string): ComponentType<BrandIconProps> {
  return function LetterIcon({ bare, size }: BrandIconProps) {
    return tileOrBare(
      bare,
      size,
      <svg viewBox="0 0 24 24" className="h-6 w-6" aria-hidden="true">
        <rect x="2" y="2" width="20" height="20" rx="5" fill={fill} />
        <text x="12" y="16.5" textAnchor="middle" fontSize="13" fontWeight="700" fontFamily="system-ui, sans-serif" fill="#ffffff">
          {letter}
        </text>
      </svg>,
    );
  };
}
export const DougsIcon = letterIcon('D', '#FF5A36');


