export function AdminIcon({ bare, size }: BrandIconProps) {
  return tileOrBare(
    bare,
    size,
    <svg viewBox="0 0 24 24" className="h-6 w-6" aria-hidden="true" fill="none" stroke="#334155" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <rect x="3" y="7" width="18" height="13" rx="2.5" />
      <path d="M9 7V5a2 2 0 0 1 2-2h2a2 2 0 0 1 2 2v2M3 12.5h18" />
    </svg>,
  );
}

// The Finance sub-app row: a bank building (pediment, columns, base) in green.
